input.command:
mkdir -p greeter && cat > greeter/greeter.go <<'EOF'
// Package greeter is a minimal example showing how dependencies are
// injected through interfaces so they can be mocked in tests.
package greeter

import "fmt"

// NameStore looks up a user's display name by ID.
type NameStore interface {
	Name(id int) (string, error)
}

// Greeter builds greetings using a NameStore.
type Greeter struct {
	Store NameStore
}

// Greet returns a greeting for the user with the given ID.
func (g Greeter) Greet(id int) (string, error) {
	name, err := g.Store.Name(id)
	if err != nil {
		return "", fmt.Errorf("lookup user %d: %w", id, err)
	}
	return "Hello, " + name + "!", nil
}
EOF
cat > greeter/greeter_test.go <<'EOF'
package greeter

import (
	"errors"
	"testing"

	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/mock"
	"github.com/stretchr/testify/require"
)

type mockStore struct {
	mock.Mock
}

func (m *mockStore) Name(id int) (string, error) {
	args := m.Called(id)
	return args.String(0), args.Error(1)
}

func TestGreet(t *testing.T) {
	store := new(mockStore)
	store.On("Name", 42).Return("Gopher", nil).Once()

	got, err := Greeter{Store: store}.Greet(42)

	require.NoError(t, err)
	assert.Equal(t, "Hello, Gopher!", got)
	store.AssertExpectations(t)
}

func TestGreetLookupError(t *testing.T) {
	errNotFound := errors.New("not found")
	store := new(mockStore)
	store.On("Name", mock.Anything).Return("", errNotFound)

	got, err := Greeter{Store: store}.Greet(7)

	require.ErrorIs(t, err, errNotFound)
	assert.Empty(t, got)
	store.AssertExpectations(t)
}
EOF
